Method.Implementation:
    Set reader = ##class(%XML.Reader).%New()
	Do reader.OpenString(obj) 


    //step 2 - extract the %XML.Document 
    Do reader.Rewind()
    #dim doc As %XML.Document
    set doc = reader.Document


    set node = doc.GetDocumentElement()
    /*

    WRITE !, "Document Node: " _ node
    Set count=doc.CountNamespace()

    Write !, "Number of namespaces in document: "_count
    For i=1:1:count { 
        Write !, "Namespace "_i_" is "_doc.GetNamespace(i)
    }

    // Show nodes in XML
     Write !,"LocalName="_node.LocalName
    If node.NodeType=$$$xmlELEMENTNODE  {
        Write !,"Namespace="_node.Namespace
    }
    If node.NodeType=$$$xmlELEMENTNODE {
        Write !,"NamespaceIndex="_node.NamespaceIndex
     }
    Write !,"Nil="_node.Nil,", NodeData="_node.NodeData," NodeId="_node.NodeId," NodeType="_node.NodeType," QName="_node.QName," HasChildNodes returns "_node.HasChildNodes()," GetNumberAttributes returns "_node.GetNumberAttributes()
    */
	Write !, "First NODE: " _ node.NodeData
	 set dynObject1 = ..ParseAllNodes(node, 1)

 Write !, dynObject1.%ToJSON()
 return dynObject1.%ToJSON()

	set daObj = ##class(%DynamicObject).%New()
	set prevNode = ""
	set dcObj = ""
	DO
	 {
		 Write !, "- ParseAllNodes: NodeData="_node.NodeData," NodeId="_node.NodeId," NodeType="_node.NodeType," QName="_node.QName," HasChildNodes returns "_node.HasChildNodes()," GetNumberAttributes returns "_node.GetNumberAttributes()

		 Set count=node.GetNumberAttributes()
		 if (count >= 1)
		 {
		    Write !, "Number of attributes: ", count
		    Set first=node.FirstAttributeName()
		    Write !, "First attribute is: ", first
		    Write !, "   Its value is: ",node.GetAttributeValue(first)
		    Do daObj.%Set("@" _ first, node.GetAttributeValue(first))
		    Set next=node.NextAttributeName(first)

		    For i=1:1:count-2 {
		        Write !, "Next attribute is: ", next
		        Write !, "   Its value is: ",node.GetAttributeValue(next)
		        Do daObj.%Set("@" _ next, node.GetAttributeValue(next))
		        Set next=node.NextAttributeName(next)
		        }
		    Set last=node.LastAttributeName()
		    Write !, "Last attribute is: ", last
		    Write !, "   Its value is: ",node.GetAttributeValue(last)
		    Do daObj.%Set("@" _ last, node.GetAttributeValue(last))
		}

        if (node.NodeType = $$$xmlELEMENTNODE)
        {
	    	Set status=node.GetText(.text)
	    	If status {
	        	// Write !, "xmlELEMENTNODE Text of the node is "_text	        
	        	// Do daObj.%Set(node.NodeData, text)
	    	}
        }
        if (node.HasChildNodes())
	    {
	    	set dcObj = ..ParseChildNode(node, first)
	    	Write !, "   =From ParseChildNode= Node: " _ node.NodeData _ ", " _ dcObj


	    }
	    if (prevNode = node.NodeData)
	    {

		    set prevObj = daObj.%Get(prevNode)
		    WRITE !, "  === CREATE ARRAY: " _ prevNode _ ", " _ prevObj.%ClassName
		    IF ($$$IsdefObject(prevObj) && prevObj.%IsA("%Library.DynamicArray") )
			{
				set dynArray = prevObj
			}
			else
			{
		    	set dynArray = ##class(%DynamicArray).%New()
		    	Do dynArray.%Push(prevObj)
			}

		    Do dynArray.%Push(dcObj)
		    WRITE !, dynArray
		    set iter = dynArray.%GetIterator()
	   			while iter.%GetNext(.key , .value ) {
	      		write "key = "_key_" , value = "_value,!
	   		}
	   		Do daObj.%Set(node.NodeData, dynArray)
	    }
	    else
	    {
		    Do daObj.%Set(node.NodeData, dcObj)
	    }
	    set prevNode = node.NodeData
	 } WHILE (node.MoveToNextSibling())
	 Write !, "ParseAllNodes: " _ daObj.%ToJSON()
	Quit daObj


	Write !, "   -- ParseChildNode: NodeData="_node.NodeData
    set stat = node.MoveToFirstChild()

	Write !, "   --- First Child NODE: NodeData="_node.NodeData," NodeId="_node.NodeId," NodeType="_node.NodeType," QName="_node.QName," HasChildNodes returns "_node.HasChildNodes()," GetNumberAttributes returns "_node.GetNumberAttributes()

	if (node.NodeType = $$$xmlELEMENTNODE)
    {

		set dcObj = ..ParseAllNodes(node, 0)
		Write !, "   *** ParseChildNode: recursive " _ recurcive _ " -- " _ node.NodeData _ " , " _ dcObj.%ToJSON()

    }
    else
    {
	    set dcObj = node.NodeData
    }
	Do node.MoveToParent()
	Write !, "   ---- ParseChildNode Output: " _ dcObj _ " NodeData="_node.NodeData
	Quit dcObj
